local function clamp(x,a,b) return math.max(a,math.min(b,x)) end
local function tween(o,t,style,dir,props) local q=TweenInfo.new(t,style or Enum.EasingStyle.Quint,dir or Enum.EasingDirection.Out); local z=TweenService:Create(o,q,props); z:Play(); return z end
local function corner(o,r) local c=Instance.new("UICorner"); c.CornerRadius=UDim.new(0,r); c.Parent=o; return c end
local function stroke(o,color,thick,trans) local s=Instance.new("UIStroke"); s.Color=color; s.Thickness=thick or 1; s.Transparency=trans or 0; s.ApplyStrokeMode=Enum.ApplyStrokeMode.Border; s.Parent=o; return s end
local function grad(o,seq,rot) local g=Instance.new("UIGradient"); g.Color=ColorSequence.new(seq); g.Rotation=rot or 0; g.Parent=o; return g end
local function frame(p,name,size,pos,color,trans,z) local f=Instance.new("Frame"); f.Name=name; f.Size=size; f.Position=pos; f.BackgroundColor3=color or C.Pink; f.BackgroundTransparency=trans or 0; f.BorderSizePixel=0; f.ZIndex=z or 1; f.Parent=p; return f end
local function text(p,name,txt,size,pos,color,z,font) local l=Instance.new("TextLabel"); l.Name=name; l.Text=txt; l.TextSize=size; l.Font=font or Enum.Font.GothamBold; l.TextColor3=color or C.White; l.BackgroundTransparency=1; l.Size=UDim2.new(1,0,0,24); l.Position=pos or UDim2.new(); l.TextXAlignment=Enum.TextXAlignment.Left; l.TextYAlignment=Enum.TextYAlignment.Center; l.ZIndex=z or 10; l.Parent=p; return l end
local function btn(p,name,txt,size,pos,z) local b=Instance.new("TextButton"); b.Name=name; b.Text=txt or ""; b.Size=size; b.Position=pos; b.AutoButtonColor=false; b.BackgroundColor3=C.Pink2; b.BackgroundTransparency=1; b.BorderSizePixel=0; b.ZIndex=z or 20; b.Parent=p; return b end

