-- UI state
local currentTab=1; local cardWidgets={}; local tabButtons={}; local buildCards; local dragging=false; local dragStart; local menuStart; local dragMoved=false

-- Ripple / touch feedback
local function ripple(parent,position) local r=frame(parent,"Ripple",UDim2.fromOffset(8,8),UDim2.fromOffset(position.X-4,position.Y-4),C.White,.38,500); corner(r,999); stroke(r,C.White,1,.25); tween(r,.46,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,{Size=UDim2.fromOffset(92,92),Position=UDim2.fromOffset(position.X-46,position.Y-46),BackgroundTransparency=1}); task.delay(.50,function() if r then r:Destroy() end end) end
local function bindTouch(button) button.InputBegan:Connect(function(i) if i.UserInputType==Enum.UserInputType.Touch or i.UserInputType==Enum.UserInputType.MouseButton1 then local p=i.Position-button.AbsolutePosition; ripple(button,Vector2.new(p.X,p.Y)); local oldSize=button.Size; tween(button,.08,Enum.EasingStyle.Quad,Enum.EasingDirection.Out,{Size=UDim2.new(oldSize.X.Scale,oldSize.X.Offset+5,oldSize.Y.Scale,oldSize.Y.Offset+2)}); task.delay(.09,function() if button and button.Parent then tween(button,.18,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{Size=oldSize}) end end) end end) end

-- Curved tab buttons: selected tab grows into a soft pill.
local function setTabVisual(i,selected,instant) local b=tabButtons[i]; if not b then return end; local dur=instant and .01 or .26; local w=selected and .92 or .84; local h=selected and 42 or 36; tween(b,dur,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,{Size=UDim2.new(w,0,0,h),BackgroundTransparency=selected and .18 or .62}); local s=b:FindFirstChildOfClass("UIStroke"); if s then tween(s,dur,Enum.EasingStyle.Quad,Enum.EasingDirection.Out,{Transparency=selected and .16 or .72,Thickness=selected and 1.5 or 1}) end; local ic=b:FindFirstChild("Icon"); local tx=b:FindFirstChild("Name"); if ic then ic.TextColor3=selected and C.White or C.Pink3 end; if tx then tx.TextColor3=selected and C.White or C.Soft end end

-- Build 8 tabs
for i,d in ipairs(TABS) do
    local b=btn(TabScroll,"Tab_"..d.name,"",UDim2.new(.84,0,0,36),UDim2.new(),84); b.BackgroundColor3=C.Pink2; corner(b,22); stroke(b,C.Pink3,1,.72); b.LayoutOrder=i
    local ic=text(b,"Icon",d.icon,15,UDim2.fromScale(.07,.08),C.Pink3,88,Enum.Font.GothamBlack); ic.Size=UDim2.fromScale(.17,.80); ic.TextXAlignment=Enum.TextXAlignment.Center
    local nm=text(b,"Name",d.name,9,UDim2.fromScale(.25,.08),d.name=="HOME" and C.White or C.Soft,88,Enum.Font.GothamBold); nm.Size=UDim2.fromScale(.68,.80); nm.TextXAlignment=Enum.TextXAlignment.Left
    tabButtons[i]=b; bindTouch(b); b.Activated:Connect(function() currentTab=i; for k=1,#TABS do setTabVisual(k,k==currentTab,false) end; ContentTitle.Text=d.name; ContentSub.Text=d.desc; Search.Text=""; CardScroll.CanvasPosition=Vector2.new(); buildCards(i); for k,w in ipairs(cardWidgets) do w.Visible=true end; task.spawn(function() for k,w in ipairs(cardWidgets) do w.BackgroundTransparency=1; task.wait(.018); if w.Parent then tween(w,.24,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{BackgroundTransparency=.42}) end end end) end)
end
TabScroll.CanvasSize=UDim2.new(0,0,0,math.max(0,TabLayout.AbsoluteContentSize.Y+8))
TabLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() TabScroll.CanvasSize=UDim2.new(0,0,0,math.max(0,TabLayout.AbsoluteContentSize.Y+8)) end)

-- Build 12 rounded cards. Each is a UI component only.
buildCards=function(index)
    for _,w in ipairs(cardWidgets) do w:Destroy() end; cardWidgets={}
    for i,d in ipairs(CARD_BANK[index]) do
        local card=btn(CardScroll,"Card_"..i,"",UDim2.fromScale(.47,.20),UDim2.new(),90); card.BackgroundColor3=C.Pink2; card.BackgroundTransparency=.42; corner(card,22); stroke(card,C.Pink3,1,.58); card.LayoutOrder=i
        local accent=frame(card,"Accent",UDim2.fromScale(.025,.72),UDim2.fromScale(.025,.14),C.Pink3,.06,91); corner(accent,9)
        local ttl=text(card,"Title",d.title,10,UDim2.fromScale(.085,.12),C.White,92,Enum.Font.GothamBold); ttl.Size=UDim2.fromScale(.75,.25)
        local ds=text(card,"Desc",d.desc,7,UDim2.fromScale(.085,.38),C.Soft,92,Enum.Font.GothamMedium); ds.Size=UDim2.fromScale(.80,.27); ds.TextWrapped=true; ds.TextYAlignment=Enum.TextYAlignment.Top
        local mode=text(card,"Mode",d.mode,7,UDim2.fromScale(.74,.76),C.Pink3,92,Enum.Font.GothamBold); mode.Size=UDim2.fromScale(.20,.16); mode.TextXAlignment=Enum.TextXAlignment.Right
        cardWidgets[i]=card; bindTouch(card)
        card.Activated:Connect(function() local old=card.BackgroundTransparency; tween(card,.10,Enum.EasingStyle.Quad,Enum.EasingDirection.Out,{BackgroundTransparency=.20}); task.delay(.11,function() if card.Parent then tween(card,.24,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,{BackgroundTransparency=old}) end end) end)
    end
    CardScroll.CanvasSize=UDim2.new(0,0,0,Grid.AbsoluteContentSize.Y+12)
end
Grid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() CardScroll.CanvasSize=UDim2.new(0,0,0,Grid.AbsoluteContentSize.Y+12) end)

-- Search filters the current tab without destroying the curved layout.
Search:GetPropertyChangedSignal("Text"):Connect(function() local q=string.lower(Search.Text or ""); for i,card in ipairs(cardWidgets) do local d=CARD_BANK[currentTab][i]; local hay=string.lower(d.title.." "..d.desc.." "..d.mode); local ok=q=="" or string.find(hay,q,1,true); card.Visible=ok end end)

-- Drag: header only, touch + mouse. Keeps the rounded shell intact.
Header.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.Touch or input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=true; dragMoved=false; dragStart=input.Position; menuStart=Menu.Position end end)
UserInputService.InputChanged:Connect(function(input) if not dragging then return end; if input.UserInputType==Enum.UserInputType.Touch or input.UserInputType==Enum.UserInputType.MouseMovement then local delta=input.Position-dragStart; if delta.Magnitude>4 then dragMoved=true end; Menu.Position=UDim2.new(menuStart.X.Scale,menuStart.X.Offset+delta.X,menuStart.Y.Scale,menuStart.Y.Offset+delta.Y) end end)
UserInputService.InputEnded:Connect(function(input) if input.UserInputType==Enum.UserInputType.Touch or input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false end end)

-- Liquid droplet intro/close. The droplet is built from frames, not an image.
local function dropletIntro() Orb.Visible=false; OrbRing.Visible=false; DropBadge.Visible=true; DropBadge.Size=UDim2.fromOffset(18,18); DropBadge.Position=UDim2.fromScale(.492,.10); DropTip.Size=UDim2.fromOffset(10,16); DropTip.Position=UDim2.new(.5,-5,.5,-8); tween(DropBadge,.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out,{Size=UDim2.fromOffset(60,60),Position=UDim2.fromScale(.435,.02)}); task.wait(.18); tween(DropBadge,.26,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{Size=UDim2.fromOffset(52,52),Position=UDim2.fromScale(.445,.02)}); task.wait(.18) end
local function openMenu() if Menu.Visible then return end; Menu.Visible=true; Menu.BackgroundTransparency=.84; Menu.Size=UDim2.fromScale(.025,.035); Menu.Position=UDim2.fromScale(.4875,.48); Menu.Rotation=-4; dropletIntro(); tween(Menu,.62,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{Size=UDim2.fromScale(.86,.80),Position=UDim2.fromScale(.07,.10),Rotation=0,BackgroundTransparency=.18}); task.wait(.08); for i,b in ipairs(tabButtons) do b.BackgroundTransparency=1; task.delay(i*.025,function() if b.Parent then tween(b,.28,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{BackgroundTransparency=(i==currentTab and .18 or .62)}) end end) end; for i,w in ipairs(cardWidgets) do w.BackgroundTransparency=1; task.delay(i*.018,function() if w.Parent then tween(w,.26,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{BackgroundTransparency=.42}) end end) end; task.delay(.35,function() DropBadge.Visible=true end) end
local function closeMenu() if not Menu.Visible then return end; tween(Menu,.48,Enum.EasingStyle.Quint,Enum.EasingDirection.In,{Size=UDim2.fromScale(.025,.035),Position=UDim2.fromScale(.4875,.48),Rotation=7,BackgroundTransparency=.84}); task.wait(.42); Menu.Visible=false; Orb.Visible=true; OrbRing.Visible=true; Orb.Size=UDim2.fromOffset(8,8); tween(Orb,.38,Enum.EasingStyle.Back,Enum.EasingDirection.Out,{Size=UDim2.fromOffset(82,82)}); DropBadge.Visible=false end
Close.Activated:Connect(closeMenu); Orb.Activated:Connect(openMenu)
bindTouch(Close); bindTouch(Orb)

-- Ambient motion: deliberately light, not a high-frequency effect engine.
local clock=0
RunService.RenderStepped:Connect(function(dt) clock+=dt; MenuGrad.Rotation=(clock*8)%360; local p=1+math.sin(clock*1.8)*.018; if Menu.Visible then MenuStroke.Transparency=.14+math.sin(clock*1.5)*.025; DropBadge.Rotation=math.sin(clock*1.6)*2; DropTip.Rotation=45+math.sin(clock*2.0)*4; OrbRing.Rotation=(clock*12)%360 end; OrbZ.Rotation=math.sin(clock*1.4)*4 end)

-- Initial state: menu is OPEN, as requested.
buildCards(1); for i=1,#TABS do setTabVisual(i,i==1,true) end; ContentTitle.Text=TABS[1].name; ContentSub.Text=TABS[1].desc; Menu.Visible=false; task.defer(openMenu)

_G.ZAKA_PINK_PANTHER_V11={Gui=GUI,Menu=Menu,Open=openMenu,Close=closeMenu,SelectTab=function(i) i=clamp(i,1,#TABS); currentTab=i; ContentTitle.Text=TABS[i].name; ContentSub.Text=TABS[i].desc; buildCards(i); for k=1,#TABS do setTabVisual(k,k==i,false) end end}

